/** WKS-REG-MSG: 864 bytes = encabezado 36 + ACA 12 + SA0 30 + SA2 47 + área de usuario 739. */
public record MensajeL002(Encabezado hdr, Aca aca, Sa0 sa0, Sa2 sa2, byte[] areaUsuario) {

    public record Encabezado(char prefijo, char aplDestino, int ccrDestino,
                             byte[] lsnOrigen,            // 9(004) o 9(08) COMP según la red: se conserva crudo
                             Estacion estacion, int ccrOrigen, int copOrigen,
                             String facultad, char aplOrigen, int resultado,
                             String mascara, String password) {
        boolean esEco() { return resultado == 31 || resultado == 32 || resultado == 33; }   // W88-MSGRES-ERR
    }
    /** STATION X(8): tipo, sucursal, privilegio y caja. */
    public record Estacion(char tipo, int sucursal, char privilegio, int caja) {}
    public record Aca(int destino, int origen) {}

    /** SA0: transacción destino 9(09) = sistema 9(04) + código 9(02) + subcódigo 9(03). */
    public record Sa0(int sistemaDestino, int codigoDestino, int subcodigoDestino,
                      int sistemaOrigen, int codigoOrigen, int subcodigoOrigen,
                      Direccion direccion, int longitud, int tiempoEspera, int respuesta) {}

    public enum Direccion { ALTA, RESP, BAJA, RES_BAJA;                 // 1, 2, 3, 4
        static Direccion de(int v) { return values()[v - 1]; }
        int codigo() { return ordinal() + 1; }
    }

    static MensajeL002 decodifica(byte[] buf) { return MensajeL002Codec.decode(buf, Charset.forName("Cp1047")); }
}

/** WKS-DATOS-S151: el movimiento que manda S264, todo en DISPLAY (dígitos EBCDIC). */
public record MovimientoS264(
        int funcion, int sistema, int producto, int instrumento, int sucursalPromotora,
        String contrato,                        // 9(16): sucursal 9(04) + número 9(08) en las últimas 12 posiciones
        List<SlotS264> slots,                   // 5 grupos CVETRANn / IND-LEYEn / ESQ-CONTn / IMPORTEn
        /* ... fechas, autorizaciones, sucursales, cajas, moneda ... */
        int bancoS264, int bancoOrigen, int bancoDestino,
        List<String> leyendas) {}               // 5 x 40 posiciones

/** CVETRAN 9(04) e IMPORTE 9(14)V99 en DISPLAY: punto decimal implícito, sin signo. */
public record SlotS264(int claveTransaccion, int indicadorLey, int esquemaContable, BigDecimal importe) {
    static SlotS264 de(String campos) {
        return new SlotS264(Integer.parseInt(campos.substring(0, 4)),
                            Integer.parseInt(campos.substring(4, 6)),
                            Integer.parseInt(campos.substring(6, 10)),
                            new BigDecimal(new BigInteger(campos.substring(10, 26)), 2));
    }
}

/** 700000-S264-A-6DIG-COMP: copia campo por campo de WKS-DATOS-S151 a WKS-MOV-DATOS. */
@Component
public class MovimientoMapper {

    public MovimientoLog151 aS151(MovimientoS264 m) {
        var slots = m.slots().stream()
                .map(s -> new SlotContable(
                        s.claveTransaccion(),          // 9(04) DISPLAY -> 9(06) COMP: se amplía sin perder valor
                        s.indicadorLey(),
                        s.esquemaContable(),
                        s.importe(),                   // 9(14)V99 DISPLAY -> 9(14)V99 COMP, misma escala
                        0, 0))
                .toList();
        return MovimientoLog151.builder()
                .funcion(m.funcion()).sistema(m.sistema()).producto(m.producto())
                .instrumento(m.instrumento()).sucursalPromotora(m.sucursalPromotora())
                .contrato(m.contrato()).slots(slots)
                .bancoS264(m.bancoS264()).bancoOrigenS264(m.bancoOrigen()).bancoDestinoS264(m.bancoDestino())
                .leyendas(m.leyendas())
                .build();                              // empaquetado COMP lo resuelve el codec de salida
    }
}

@Configuration
@RequiredArgsConstructor
public class ReceptorL002Flow {

    private final RegistroL002Handler handler;
    private final ReceptorProperties props;    // agenda-entrada, agenda-salida: "OUTPUT OF LINEA"

    @Bean
    IntegrationFlow receptorL002(ConnectionFactory mq) {
        return IntegrationFlow
                .from(Jms.messageDrivenChannelAdapter(mq).destination(props.agendaEntrada()))   // RECEIVE COMS-IN
                .transform(byte[].class, MensajeL002::decodifica)
                .filter(MensajeL002.class, m -> m.sa0().sistemaDestino() == 151)    // W88-SA0-TRN-DSIS-S151
                .filter(MensajeL002.class, m -> !m.hdr().esEco(),                   // RSLTDO 31, 32, 33
                        f -> f.discardFlow(d -> d.handle(m -> monitor.registra("MENSAJE DE ECO", m))))
                .wireTap(monitor.canal())                                           // 060950-ESCRIBE-MONITOR
                .handle(handler)
                .transform(MensajeL002.class, MensajeL002::codifica)
                .handle(Jms.outboundAdapter(mq).destination(props.agendaSalida()))  // SEND COMS-OUT
                .get();
    }
    // Timeout de 20 s, ACCEPT y HI del operador ya no existen: el contenedor JMS espera,
    // y el apagado ordenado (HI 4 / HI 6 -> DISABLE PROGRAM) es el shutdown de Spring.
}

@Component
@RequiredArgsConstructor
public class RegistroL002Handler {

    private final Registras registras;            // CARGAMOV1 IN LIB-REGISTRA (CTRLVERS S151L002R264)
    private final MovimientoMapper mapper;
    private final ReceptorProperties props;       // subcodigos-habilitados: [264]

    @ServiceActivator
    public MensajeL002 registra(MensajeL002 msg) {
        int resultado;
        MovimientoS264 mov = MovimientoS264.de(msg.areaUsuario());
        Long autS151 = null;
        if (props.subcodigosHabilitados().contains(msg.sa0().subcodigoDestino())) {
            try {
                var r = registras.cargaMovimiento(mapper.aS151(mov));
                resultado = r.codigo();
                if (resultado == 0) autS151 = r.autorizacionS151();     // WKS-MOV-AUT-S151
            } catch (RegistrasNoDisponibleException e) {               // DAME_TIT con estatus distinto de 0
                log.error(" >> ERROR NO SE ENCUENTA LIBRERIA: {} >>>", mov.funcion());
                resultado = props.resultadoLibreriaNoDisponible();     // ver riesgo: en COBOL queda en 0
            }
        } else {
            log.warn(" >>NO SE PUEDE PROCESAR MENSAJE, SIST. INVALIDO: {} >>>", msg.sa0().subcodigoDestino());
            resultado = 99;
        }
        return Respuesta.de(msg, resultado, mov.conAutorizacion(autS151));   // 201040-ARMA-MSG-SAL
    }
}

/**
 * 201010-EXTRAE-L002: por cada mensaje se consulta en CTRLVERS el título vigente de la librería
 * y se reasigna LIB-REGISTRA; después de CARGAMOV1 se hace CANCEL.
 * En Spring la versión de la librería es la versión desplegada del bean; si se necesita
 * elegir implementación por sistema, se resuelve una vez al arrancar.
 */
@Configuration
class RegistrasResolver {
    @Bean
    Map<Integer, Registras> registrasPorSistema(List<Registras> impls) {
        return impls.stream().collect(Collectors.toMap(Registras::sistema, Function.identity()));
    }
}

final class Respuesta {
    static final int LONGITUD_SA0 = 737;     // WKS-SA0-LONG y CS-COMS-OUT-TEXT-LENGTH

    /** 201040-ARMA-MSG-SAL: invierte ACA y CCR, dirección 2 (RESP) y área de usuario = resultado + datos. */
    static MensajeL002 de(MensajeL002 in, int resultado, MovimientoS264 datos) {
        var hdr = in.hdr().conCcr(in.hdr().copOrigen(), in.hdr().ccrDestino());   // CCRDEST <-> COPORGN
        var aca = new MensajeL002.Aca(in.aca().origen(), in.aca().destino());      // destino <-> origen
        var sa0 = in.sa0().conDireccion(MensajeL002.Direccion.RESP).conLongitud(LONGITUD_SA0);
        byte[] area = MsgSal.de(resultado, datos).toBytes();                      // MSG-SAL-RESULT-L002 + MENSAJE
        return new MensajeL002(hdr, aca, sa0, in.sa2(), area);
    }
}

// El adaptador de salida trata como aceptado el estatus 0 y el 96; cualquier otro
